 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if set(cells) == border:
                boxes.append((r0, r1, c0, c1, color, border))

    border_cells = set().union(*(b[5] for b in boxes)) if boxes else set()
    marker_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                           if grid[r][c] != 0 and (r, c) not in border_cells)
    out = [[0] * w for _ in range(h)]
    for r0, r1, c0, c1, color, border in boxes:
        for r, c in border:
            out[r][c] = color
        interior = [(r, c) for r in range(r0 + 1, r1)
                    for c in range(c0 + 1, c1) if (r + c) % 2 == 0]
        n = len(interior)
        candidates = [m for m, count in marker_counts.items() if m != color and count == n]
        if candidates:
            fill = min(candidates)
            for r, c in interior:
                out[r][c] = fill
    return out
